{
  "schema_version": 1,
  "action": "set_policy",
  "policy": {
    "model": "transformer",
    "window": 3,
    "threshold_q": 0.999,
    "persistence": 3
  },
  "intent_understood_as": "minimize_false_alarms",
  "reason": "Intent demands minimal false alarms while keeping DNS attacks genuinely detected. Transformer avoids catastrophic per-attack failures and has the lowest DNS delay (10.9s) at default. Using q=0.999 (not 0.9999) and persistence=3 suppresses false alarms aggressively (transformer already ~0.01/h at default) while preserving sustained DNS detection, respecting the hard constraint that known attacks must still be detected."
}
